#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] prefix, [x..n-y-1] middle, [n-y..n-1] suffix
    // result: suffix + middle + prefix
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n; placed++){
        // Find where (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue; // already in place

        // Step 1: Move element from pos to position (n-1) if not already there
        if(pos != n-1){
            // We want to move p[pos] to the last position
            // Use x = pos+1, y = n-1-pos
            // This gives: suffix=[pos+1..n-1], middle=empty check: x+y = pos+1+n-1-pos = n, need x+y < n
            // So middle would be empty - not allowed. We need x+y < n.
            // Use x = pos, y = n-1-pos if pos > 0
            // Then prefix=[0..pos-1], middle=[pos..pos]=just our element, suffix=[pos+1..n-1]
            // Result: [pos+1..n-1] + [pos] + [0..pos-1]
            // Our element goes to position (n-1-pos) which is after suffix
            if(pos > 0 && (n-1-pos) > 0 && pos + (n-1-pos) < n) {
                int x = pos, y = n-1-pos;
                ops.push_back({x, y});
                apply_op(p, x, y);
                // element is now at position y = n-1-pos
                pos = y; // = n-1-pos
            } else if(pos == 0) {
                // element at position 0, need to get it to n-1
                // x=1, y=1, need 1+1<n => n>2 (guaranteed n>=3)
                // prefix=[0], middle=[1..n-2], suffix=[n-1]
                // result: [n-1] + [1..n-2] + [0] => element goes to position n-1
                int x=1, y=1;
                ops.push_back({x, y});
                apply_op(p, x, y);
                pos = n-1;
            }
        }

        if(pos == placed) continue;

        // Step 2: Element should be at some position pos. Move it to position 'placed'.
        // Find it again to be safe
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Use x = placed, y = n - pos if placed > 0
        // prefix=[0..placed-1], suffix=[pos..n-1], middle=[placed..pos-1]
        // result: [pos..n-1] + [placed..pos-1] + [0..placed-1]
        // element at pos goes to position 0... we want it at placed
        // Use x = placed+1, y = n-pos; need placed+1+n-pos < n => placed+1 < pos; pos > placed+1
        if(pos > placed + 1 && placed+1 > 0 && (n-pos) > 0) {
            ops.push_back({placed+1, n-pos});
            apply_op(p, placed+1, n-pos);
        } else if(pos == placed + 1 && pos < n-1) {
            // adjacent: x=placed+1, y=1, need placed+2<n
            if(placed+2 < n) { ops.push_back({placed+1,1}); apply_op(p,placed+1,1); }
        } else if(pos == n-1 && placed == 0) {
            ops.push_back({1, 1}); apply_op(p, 1, 1);
            // This puts [n-1]+[1..n-2]+[0] - element at n-1 goes to 0
        }
        // re-find and verify
        for(int i=0;i<n;i++) if(p[i]==placed+1 && i!=placed) {
            // fallback: try all valid (x,y) that put element at placed
            for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
                vector<int> tmp=p; apply_op(tmp,x,y);
                if(tmp[placed]==placed+1){ ops.push_back({x,y}); p=tmp; goto done; }
            }
        }
        done:;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
